const SV_F='font-family="Nunito Sans, sans-serif"';
const SV_T=(x,y,t,o={})=>`<text x="${(+x).toFixed(1)}" y="${(+y).toFixed(1)}" ${SV_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}"${o.op?` fill-opacity="${o.op}"`:''}>${t}</text>`;
const SV_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${(+x1).toFixed(1)}" y1="${(+y1).toFixed(1)}" x2="${(+x2).toFixed(1)}" y2="${(+y2).toFixed(1)}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const SV_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw??2}"${o.ex?' '+o.ex:''}/>`;
const SV_arrow=(x1,y1,x2,y2,col='#18213A',w=3,h=16)=>{const a=Math.atan2(y2-y1,x2-x1);return SV_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const SV_poly=(pts,col,w=4,ex='')=>`<polyline points="${pts.map(p=>(+p[0]).toFixed(1)+','+(+p[1]).toFixed(1)).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${ex}/>`;
const SV_dot=(x,y,r,col,ex='')=>`<circle cx="${(+x).toFixed(1)}" cy="${(+y).toFixed(1)}" r="${r}" fill="${col}" ${ex}/>`;
const SV_tri=(x,y,s,col)=>`<polygon points="${x},${y-s} ${x-s*.9},${y+s*.6} ${x+s*.9},${y+s*.6}" fill="${col}" stroke="#fff" stroke-width="2"/>`;
const SV_GREY='#5C6577', SV_DARK='#343A40', SV_EARTH='#C8A27A', SV_LAND='#8CBF73', SV_WATER='#74C0FC';
/* the readings of the worked example and their number line */
const SV_RD=[100.02,100.04,100.03,100.05,100.01];
/* a level line under a horizontal line: x0..x1 at height y, falling by drop px at the far end (a parabola, as c = d²/2R) */
const SV_curve=(x0,x1,y,drop,n=24)=>Array.from({length:n+1},(_,i)=>{const t=i/n;return [x0+(x1-x0)*t,y+drop*t*t]});
/* two circles: centres a, b, radii r1, r2 -> their two crossing points */
const SV_cut=(ax,ay,r1,bx,by,r2)=>{const d=Math.hypot(bx-ax,by-ay),a=(r1*r1-r2*r2+d*d)/(2*d),h=Math.sqrt(r1*r1-a*a),ux=(bx-ax)/d,uy=(by-ay)/d,mx=ax+a*ux,my=ay+a*uy;return [[mx-h*uy,my+h*ux],[mx+h*uy,my-h*ux]]};
const SV_ring=(x,y,r,col,w=2.5,ex='')=>`<circle cx="${(+x).toFixed(1)}" cy="${(+y).toFixed(1)}" r="${r}" fill="none" stroke="${col}" stroke-width="${w}" ${ex}/>`;
const SV_target=(x,y,r)=>SV_dot(x,y,r,'#fff','stroke="#ADB5BD" stroke-width="2"')+SV_ring(x,y,r*.62,'#ADB5BD',2)+SV_ring(x,y,r*.26,'#ADB5BD',2)+SV_L(x-r,y,x+r,y,'#DEE2E6',1.5)+SV_L(x,y-r,x,y+r,'#DEE2E6',1.5);

