function EXTRA(R,ICON){
 /* hook: a river, two banks, two bridge halves built from each bank that do not line up */
 ICON.svBridge=(x,y)=>{let s=`<rect x="0" y="150" width="460" height="70" rx="10" fill="${SV_WATER}" fill-opacity=".7"/>`+
  `<polygon points="0,120 90,120 120,220 0,220" fill="${SV_LAND}"/><polygon points="460,120 370,120 340,220 460,220" fill="${SV_LAND}"/>`+
  `<rect x="150" y="104" width="22" height="80" fill="${SV_GREY}"/><rect x="288" y="104" width="22" height="80" fill="${SV_GREY}"/>`+
  `<rect x="20" y="92" width="196" height="18" rx="3" fill="${BLU}"/><rect x="246" y="112" width="194" height="18" rx="3" fill="${ORG}"/>`+
  SV_T(231,76,'?',{fs:56,fw:800,a:'middle',fill:MAG})+SV_T(100,250,'crew 1',{fs:24,fw:800,a:'middle',fill:BLU})+SV_T(360,250,'crew 2',{fs:24,fw:800,a:'middle',fill:ORG});
  return `<g transform="translate(${x-230} ${y-130})">${s}</g>`};
 /* hook: one control framework of three points shared by both banks */
 ICON.svControl=(x,y)=>{const A=[40,110],B=[180,20],C=[320,110];
  const s=SV_L(A[0],A[1],B[0],B[1],GRN,3,'stroke-dasharray="8 6"')+SV_L(B[0],B[1],C[0],C[1],GRN,3,'stroke-dasharray="8 6"')+SV_L(A[0],A[1],C[0],C[1],GRN,3,'stroke-dasharray="8 6"')+
   SV_tri(A[0],A[1],16,GRN)+SV_tri(B[0],B[1],16,GRN)+SV_tri(C[0],C[1],16,GRN)+SV_T(180,98,'one framework',{fs:26,fw:800,a:'middle',fill:GRN});
  return `<g transform="translate(${x-180} ${y-70})">${s}</g>`};
 /* recap pictures, each about 420 x 330 */
 ICON.svRecap1=(x,y)=>{let s=`<polygon points="30,300 210,30 390,300" fill="${BLU}" fill-opacity=".10" stroke="${BLU}" stroke-width="5"/>`+SV_tri(30,300,18,BLU)+SV_tri(210,30,18,BLU)+SV_tri(390,300,18,BLU);
  [[150,240],[190,200],[240,250],[270,210],[210,150]].forEach(([a,b2])=>{s+=SV_dot(a,b2,8,ORG)});
  const [q1]=SV_cut(150,240,70,270,210,80);s+=SV_ring(150,240,70,GRN,2.5,'stroke-dasharray="6 5"')+SV_ring(270,210,80,GRN,2.5,'stroke-dasharray="6 5"')+SV_dot(q1[0],q1[1],11,GRN);
  return `<g transform="translate(${x-210} ${y-165})">${s}</g>`};
 ICON.svRecap2=(x,y)=>{const pts=SV_curve(30,340,70,190);
  const s=SV_L(30,70,340,70,SV_GREY,4)+SV_poly(pts,ORG,6)+SV_dot(30,70,10,SV_DARK)+SV_T(185,50,'10 km',{fs:28,fw:800,a:'middle',fill:SV_GREY})+
   SV_L(372,70,372,260,SV_DARK,4)+SV_L(358,70,386,70,SV_DARK,4)+SV_L(358,260,386,260,SV_DARK,4)+SV_T(372,300,'7.85 m',{fs:30,fw:800,a:'middle',fill:ORG});
  return `<g transform="translate(${x-210} ${y-165})">${s}</g>`};
 ICON.svRecap3=(x,y)=>{let s=SV_target(105,150,95)+SV_target(315,150,95);
  [[44,-32],[54,-24],[38,-20],[50,-40],[60,-30]].forEach(([dx,dy])=>{s+=SV_dot(105+dx,150+dy,9,PUR)});
  s+=SV_arrow(150,118,112,148,GRN,4,14);
  [[-60,-20],[48,44],[16,-68],[-36,56],[64,-12]].forEach(([dx,dy])=>{s+=SV_dot(315+dx,150+dy,9,ORG)});
  s+=SV_T(105,290,'bias: correct',{fs:26,fw:800,a:'middle',fill:PUR})+SV_T(315,290,'scatter: average',{fs:26,fw:800,a:'middle',fill:ORG});
  return `<g transform="translate(${x-210} ${y-165})">${s}</g>`};
}
